import * as React from "react"

function ConfirmOtpForm({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="confirm-otp-form"
      className={className}
      {...props}
    >
      <div className="flex flex-1 flex-col  justify-center space-y-5 max-w-md mx-auto mt-24">
          <div className="flex flex-col space-y-2 text-center">
              <h2 className="text-3xl md4xl font-bold">Confirm OTP</h2>
              <p className="text-md md">
                  Enter the OTP we just sent you.
              </p>
          </div>
          <div className="flex flex-col max-w-md space-y-5">
              <input type="text" placeholder="otp"
                    className="flex px-3 py-2 md4 md3 border-2 border-black rounded-lg font-medium placeholder" />
              <button className="flex items-center justify-center flex-none px-3 py-2 md4 md3 border-2 rounded-lg font-medium border-black bg-black text-white">
                  Confirm
              </button>
          </div>
      </div>
    </div>
  )
}

export { ConfirmOtpForm }
